        this.baseSkillCooldown = 1.8; // 基础技能冷却

        // 移动AI行为
        this._behaviorTimer = 3 + Math.random() * 4; // 行为切换计时器
        this._circling = false; // 是否绕行玩家
        this._circleDir = 1; // 绕行方向 (1 或 -1)

        // 持续技能效果
        this._sustainedEffect = null;

        // 预警线
