		_safeRoundRect(ctx, btnX, btnY, btnW, btnH, 10);
		ctx.fill();
		ctx.strokeStyle = '#ff4444';
		ctx.lineWidth = 2;
		ctx.stroke();
		ctx.fillStyle = '#ff4444';
		ctx.font = 'bold 16px sans-serif';
		ctx.fillText('返回主菜单', w / 2, btnY + 28);

		this.continueBtnArea = { x: btnX, y: btnY, w: btnW, h: btnH };
		ctx.textAlign = 'left';
		ctx.restore();
