    LootGoblin: { hp: 500, speed: 200, radius: 14, damage: 0, xp: 0, draw: drawLootGoblin, behavior: 'flee' },
    Splitter: { hp: 60, speed: 80, radius: 10, damage: 10, xp: 12, draw: drawSwarmDrone, deathEffect: 'split' },
