			ctx.fillStyle = '#ff6666';
			ctx.font = '12px sans-serif';
			ctx.textAlign = 'center';
			ctx.fillText('🔒 ' + BuildPreset.getUnlockConditionText(build, this.game.meta), x + cw / 2, y + ch / 2 - 8);

