		ctx.font = 'bold 18px sans-serif';
		ctx.textAlign = 'center';
		ctx.fillText('诅咒契约', w / 2, 28 + topOffset);
		ctx.fillStyle = '#aaaaaa';
		ctx.font = '10px sans-serif';
		ctx.fillText('主动叠加诅咒，换取更多芯片奖励', w / 2, 44 + topOffset);
