			ctx.lineWidth = 1.5;
			ctx.stroke();

			// 文字
			ctx.font = 'bold 12px sans-serif';
			ctx.fillStyle = act.enabled ? act.color : '#555';
			ctx.textAlign = 'center';
			ctx.fillText(act.label, bx + btnW / 2, btnY + btnH / 2 + 4);
