                        p.plagueSpread = true;
                        if (!this._notifiedSets.has(setKey3)) { this._notifiedSets.add(setKey3); this.game.spawnDamageNumber(p.x, p.y - 60, elName + ' 3\u4EF6\u5957: \u6BD2\u7206\u4F20\u64AD', elColor); }
