        let cd = base * (1 - cdr);

        // 杩涘寲鍚庡喎鍗寸缉鍑忔瘮鐜囷紙濡0.4=鍐荤粨鏃堕棿60%鍑忓皯锛
        // 杩涘寲鍚庡喎鍗寸缉鍑忔瘮鐜囷紙濡0.4=鍐荤粨鏃堕棿60%鍑忓皯锛
